Platform_GetUnitStateObservation={module='Platform/unit_states.lua',member='Platform.GetUnitStateObservation',callName='addon.Platform:GetUnitStateObservation',description='Observe death or ghost state, or friendliness to the player, for the exact selected unit on probe-policy clients. A missing, failed, restricted or malformed required observation is unavailable. Unit absence is unavailable rather than a negative match, including under NOT. No cross-poll state is retained.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},unit={type='string',description='Exact nonempty unit token to observe.'},kind={type='string',description='Exactly dead for UnitIsDeadOrGhost, or friendly for UnitIsFriend(player, unit).'}},returns={{type='boolean | nil',description='Readable current state, or nil when unavailable.'},{type='string | nil',description='Availability or query-validation reason when no current state can be read.'}}},
Platform_GetUnitPresenceObservation={
 module='Platform/unit_presence.lua',member='Platform.GetUnitPresenceObservation',callName='addon.Platform:GetUnitPresenceObservation',
